def until(fn,why,timeout=30):
    end=time.monotonic()+timeout
    while time.monotonic()<end:
        try:
            v=fn()
            if v:return v
        except Exception:
            pass
        time.sleep(.25)
    raise AssertionError(why)

def isolated_env(root):
    if root.exists(): shutil.rmtree(root)
    (root/"localappdata"/"flyExplorer").mkdir(parents=True)
    (root/"appdata").mkdir()
    (root/"temp").mkdir()
    (root/"localappdata"/"flyExplorer"/"ui-preferences-v1.txt").write_text(
        "schema=2\r\nlanguage=ko-KR\r\ntheme=dark\r\nview=large-icons\r\n",
        encoding="ascii",newline="")
    env=os.environ.copy()
    env["LOCALAPPDATA"]=str(root/"localappdata")
    env["APPDATA"]=str(root/"appdata")
    env["TEMP"]=env["TMP"]=str(root/"temp")
    for k in ("FLY_M23_OWNED_DRAG_TEST","FLY_M23_OWNED_SESSION","FLY_M23_OWNED_DRAG_TRACE"):
        env.pop(k,None)
    return env

def row_key(name):
    for key,names in TARGETS:
        if any(n in name for n in names):
            return key
    return None

def snap_control(ctrl):
    if ctrl.rectangle().width()==0:
        try: ctrl.scroll_into_view()
        except Exception:
            try: ctrl.iface_scroll_item.ScrollIntoView()
            except Exception: pass
        time.sleep(.3)
    if ctrl.rectangle().width()==0:return None
    return ctrl.capture_as_image().convert("RGB")

def launch_fly(exe, env_root, expected_image_name):
    env=isolated_env(env_root)
    proc=subprocess.Popen([str(exe),str(PROFILE)],cwd=exe.parent,env=env)
    win=None
    result={}
    try:
        def getwin():
            if proc.poll() is not None:return None
            ws=[w for w in Desktop(backend="uia").windows(process=proc.pid)
                if "flyExplorer" in w.window_text()]
            return ws[0] if len(ws)==1 else None
        win=until(getwin,str(exe)+": window missing")
        try: win.move_window(x=40,y=40,width=972,height=720,repaint=True)
        except Exception: pass
        time.sleep(3)
        files=[x for x in win.descendants() if x.element_info.automation_id=="LeftFiles"]
        if len(files)!=1: raise AssertionError("LeftFiles ambiguous")
        rows=[x for x in files[0].descendants() if x.element_info.control_type=="ListItem"]
        mapped={}
        for row in rows:
            name=row.element_info.name or row.window_text()
            key=row_key(name)
            if key and key not in mapped:mapped[key]=(row,name)
        print("FLY_MAPPED_KEYS",sorted(mapped),flush=True)
        if len(mapped)!=6: raise AssertionError("did not map all six Known Folder rows")
        for key,_ in TARGETS:
            row,name=mapped[key]
            imgs=[x for x in row.descendants() if x.element_info.control_type=="Image"]
            names=[x.element_info.name for x in imgs]
            matching=[x for x in imgs if x.element_info.name==expected_image_name]
            if len(matching)!=1:
                raise AssertionError(key+": expected "+expected_image_name+" got "+repr(names))
            icon=snap_control(matching[0])
            rowimg=snap_control(row)
            if icon is None or rowimg is None:
                raise AssertionError(key+": screenshot missing")
            result[key]=(rowimg,hashlib.sha256(icon.tobytes()).hexdigest())
            print("FLY_VISUAL",key,repr(name),"ICON_SHA256",result[key][1],
                  "ROW_SIZE",rowimg.size,flush=True)
    finally:
        if proc.poll() is None:
            if win is not None:
                c.windll.user32.PostMessageW(win.handle,0x10,0,0)
                try:proc.wait(timeout=8)
                except subprocess.TimeoutExpired:
                    proc.terminate();proc.wait(timeout=5)
            else:
                proc.terminate();proc.wait(timeout=5)
    print("FLY_EXIT",str(exe),proc.returncode,flush=True)
    if proc.returncode!=0: raise AssertionError(str(exe)+": nonzero exit")
    return result

def launch_explorer():
    desktop=Desktop(backend="uia")
    before=set()
    for w in desktop.windows(control_type="Window"):
        try:
            if psutil.Process(w.element_info.process_id).name().lower()=="explorer.exe":
                before.add(w.handle)
        except Exception:pass
    subprocess.Popen(["explorer.exe","/separate,",str(PROFILE)])
    win=None
    result={}
    try:
        def getwin():
            for w in Desktop(backend="uia").windows(control_type="Window"):
                try:
                    if w.handle in before:continue
                    if psutil.Process(w.element_info.process_id).name().lower()!="explorer.exe":continue
                    return w
                except Exception:pass
            return None
        win=until(getwin,"Explorer window missing",20)
        try: win.move_window(x=40,y=40,width=972,height=720,repaint=True)
        except Exception: pass
        win.set_focus();send_keys("^+2");time.sleep(1.5)
        rows=[x for x in win.descendants() if x.element_info.control_type=="ListItem"]
        mapped={}
        for row in rows:
            name=row.element_info.name or row.window_text()
            key=row_key(name)
            if key and key not in mapped:mapped[key]=(row,name)
        print("EXPLORER_MAPPED_KEYS",sorted(mapped),flush=True)
        if len(mapped)!=6: raise AssertionError("Explorer did not map all six Known Folder rows")
        for key,_ in TARGETS:
            row,name=mapped[key]
            img=snap_control(row)
            if img is None: raise AssertionError("Explorer "+key+": screenshot missing")
            result[key]=img
            print("EXPLORER_VISUAL",key,repr(name),"ROW_SIZE",img.size,flush=True)
    finally:
        if win is not None:
            try:win.close()
            except Exception:pass
    return result

def fit(img,w=180,h=150):
    out=Image.new("RGB",(w,h),"white")
    cp=img.copy();cp.thumbnail((w-8,h-8))
    out.paste(cp,((w-cp.width)//2,(h-cp.height)//2))
    return out

